        box=ui.column();ui.pad(box,12,4,12,12);ScrollView scroll=new ScrollView(host);scroll.setFillViewport(true);scroll.setVerticalScrollBarEnabled(true);scroll.addView(box);shell.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        LinearLayout source=panels.section(box,"添加来源","公开介绍与原图，最多3个来源","link","01");links=input(source,"作品链接（每行一个）",2);button(source,"提取介绍","find",()->extract(false));button(source,"手动粘贴","selectAll",()->extract(true));sourceBox=ui.column();source.addView(sourceBox);
        keepOriginal=new CheckBox(host);keepOriginal.setText("正文无需翻译");keepOriginal.setTextSize(14);keepOriginal.setTextColor(ui.text);keepOriginal.setButtonTintList(android.content.res.ColorStateList.valueOf(ui.accent));source.addView(keepOriginal);controls.add(keepOriginal);text(source,"原文已是中文时直接带入，不消耗AI次数。");material=input(source,"补充素材（可选）",2);text(source,"只填写公开作品介绍，不要包含密码或私人资料。");
