        customBox=ui.column();service.addView(customBox);address=input(customBox,"API 地址（HTTPS）",1);key=input(customBox,"API Key（按服务要求，可留空）",1);key.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);key.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO);model=input(customBox,"模型名称",1);
