    private void save()throws Exception{save(true);}
    private void save(boolean validate)throws Exception{if(host.account()==null||host.account().optLong("id")!=owner)throw new java.io.IOException("账号已切换");if(validate&&custom()){AiClient.endpoint(address.getText().toString());if(model.getText().toString().trim().isEmpty())throw new java.io.IOException("请填写模型名");}settings.save(owner,ServiceEndpoint.origin(),new JSONObject().put("custom",custom()).put("address",address.getText().toString().trim()).put("key",key.getText().toString().trim()).put("model",model.getText().toString().trim()));}
    private <T> void run(MainActivity.Work<T> work,Consumer<T> done){if(busy||!live())return;final long id=++serial;busy=true;for(View v:controls)v.setEnabled(false);progress.setVisibility(View.VISIBLE);cancelAction.setVisibility(View.VISIBLE);status.setText("正在处理，请稍候。原标题将保持不变。");host.task(work,value->{if(!live()||id!=serial)return;busy=false;for(View v:controls)v.setEnabled(true);progress.setVisibility(View.GONE);cancelAction.setVisibility(View.GONE);done.accept(value);},message->{if(!live()||id!=serial)return;busy=false;for(View v:controls)v.setEnabled(true);progress.setVisibility(View.GONE);cancelAction.setVisibility(View.GONE);status.setText(message);});}
    private void cancel(){serial++;client.close();client=new AiClient();busy=false;for(View v:controls)v.setEnabled(true);progress.setVisibility(View.GONE);cancelAction.setVisibility(View.GONE);status.setText("已取消。内置生成若已开始仍计次，可恢复上次结果。不会自动重试。");}
    private void extract(boolean manual){
        final String[] urls=links.getText().toString().trim().split("\\s+");if(urls.length<1||urls.length>3){status.setText("请输入1至3个作品链接");return;}
        AiClient io=client;run(()->{JSONArray found=new JSONArray();for(String raw:urls){String u=AiClient.sourceUrl(raw).toString();found.put(manual?new JSONObject().put("url",u).put("text","").put("cover",""):io.source(u));}return found;},found->{if(sources.length()>0){proofUrl="";refreshProof();}sources=found;importAction.setVisibility(View.GONE);generate.setText("生成草稿");previewBox.setVisibility(View.GONE);if(guidance!=null)guidance.suggest(found);previous=null;result=null;previewBox.removeAllViews();recover.setVisibility(View.GONE);sourceBox.removeAllViews();controls.removeAll(sourceInputs);controls.removeAll(sourceTitles);sourceInputs.clear();sourceTitles.clear();for(int i=0;i<sources.length();i++){JSONObject s=sources.optJSONObject(i);JSONArray bs=s.optJSONArray("blocks");int pictures=0;if(bs!=null)for(int n=0;n<bs.length();n++)if("image".equals(bs.optJSONObject(n).optString("kind")))pictures++;text(sourceBox,"来源 "+(i+1)+" · 完整介绍 / "+pictures+"张图片\n"+s.optString("url"));EditText originalTitle=input(sourceBox,"原标题（保持原语言）",1);originalTitle.setText(s.optString("title"));sourceTitles.add(originalTitle);EditText e=input(sourceBox,"公开介绍",3);e.setText(s.optString("text"));if(bs!=null&&bs.length()>0){e.setFocusable(false);e.setTextIsSelectable(true);}sourceInputs.add(e);}status.setText(manual?"粘贴作品介绍后生成":"已提取详细介绍和图片；不会用网页摘要替代，也不会精简原文");});
    }
    private String token(){JSONObject saved=identity.load(owner,ServiceEndpoint.origin());try{if(saved!=null&&saved.getJSONObject("user").getLong("id")==owner&&java.time.Instant.parse(saved.getString("expires_at")).toEpochMilli()>System.currentTimeMillis())return saved.getString("token");}catch(Exception ignored){}return "";}
    private void generate(boolean restore){
        if(busy||!live())return;
        try{
            if(!keepOriginal.isChecked())save();if(!custom()&&!keepOriginal.isChecked()&&token().isEmpty()){dialog().setTitle("认证仓库账号").setMessage("内置AI按仓库UID分配额度。把当前官网会话交给星屿服务验证，不保存官网密码或会话。所选介绍交给Cloudflare AI处理，草稿缓存1小时。").setNegativeButton("取消",null).setPositiveButton("认证并继续",(d,w)->run(()->host.client().enablePrivateMessaging(owner),session->{try{if(session.getJSONObject("user").getLong("id")!=owner)throw new Exception("认证账号不符");identity.save(owner,ServiceEndpoint.origin(),session);generate(restore);}catch(Exception e){status.setText(e.getMessage());}})).show();return;}
            if(!restore){if(sources.length()==0)throw new Exception("请先提取链接，或使用链接配合手动素材");for(int i=0;i<sources.length();i++)sources.getJSONObject(i).put("text",sourceInputs.get(i).getText().toString()).put("title",sourceTitles.get(i).getText().toString());previous=SourceTranslation.request(sources,material.getText().toString().trim(),guidance==null?"auto":guidance.guide.transportType(guidance.kind()),UUID.randomUUID().toString());if(!custom()&&!keepOriginal.isChecked()){JSONArray planned=new JSONArray(previous.getJSONArray("sources").toString());if(!previous.optString("material").isEmpty())planned.getJSONObject(0).getJSONArray("blocks").put(new JSONObject().put("kind","p").put("text",previous.getString("material")));if(new SourceTranslation.Plan(planned).chunks.size()>8||previous.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8).length>200000){previous=null;throw new Exception("详细介绍较长，内置免费预算无法完整翻译。请选择自定义AI，原文不会被截断");}}}
            if(previous==null)throw new Exception("没有可恢复的任务");if(keepOriginal.isChecked()){JSONArray original=new JSONArray(previous.getJSONArray("sources").toString());if(!previous.optString("material").trim().isEmpty())original.getJSONObject(0).getJSONArray("blocks").put(new JSONObject().put("kind","p").put("text",previous.getString("material")));SourceTranslation.Plan plan=new SourceTranslation.Plan(original);Map<String,String> values=new HashMap<>();for(JSONArray chunk:plan.chunks)for(int i=0;i<chunk.length();i++){JSONObject v=chunk.getJSONObject(i);values.put(v.getString("id"),v.getString("text"));}result=plan.assemble(original,"auto",values);preview();status.setText("已按原文带入，未调用AI、未消耗内置次数");recover.setVisibility(View.GONE);return;}final JSONObject data=new JSONObject(previous.toString());final boolean own=custom();final String a=address.getText().toString(),k=key.getText().toString(),m=model.getText().toString(),secret=token();final AiClient io=client;recover.setVisibility(own?View.GONE:View.VISIBLE);
            run(()->{if(own)return new JSONObject().put("draft",io.custom(a,k,m,data));JSONObject response;try{response=io.json(new java.net.URL(ServiceEndpoint.origin()+"/ai/v2/draft"),SourceTranslation.builtinBodyOnlyRequest(data),secret,true);}catch(AiClient.Failure e){if(e.status==401)identity.clear(owner);throw e;}response.put("draft",SourceTranslation.restoreOriginalSourceTitles(response.getJSONObject("draft"),data));AiClient.validate(response.getJSONObject("draft"),sources,true);return response;},response->{result=response.optJSONObject("draft");preview();status.setText(own?"草稿已生成，请核对来源后导入":"今日个人剩余 "+response.optInt("remaining")+" 次 · 共享翻译预算剩余 "+response.optInt("shared_remaining")+" 段");});
        }catch(Exception e){status.setText(e.getMessage());}
    }
    private CheckBox check(LinearLayout parent,String label,boolean value){CheckBox c=new CheckBox(host);c.setText(label);c.setTextSize(13);c.setTextColor(ui.text);c.setButtonTintList(android.content.res.ColorStateList.valueOf(ui.accent));c.setChecked(value);parent.addView(c);controls.add(c);return c;}
    private void preview(){try{
        previewBox.removeAllViews();previewBox.setVisibility(View.VISIBLE);LinearLayout card=panels.section(previewBox,"确认草稿","原标题保留，导入前仍可手动修改","selectAll","03");panels.note(card,"只翻译正文，图片原样保留。导入只修改本机草稿，不会自动发表。");draftTitle=input(card,"投稿标题（默认使用原标题）",2);draftTitle.setText(defaultTitle(result.optString("title")));if(result.optString("title").isEmpty())text(card,"未提取到原标题，请补充作品名称。");
        if(guidance!=null){button(card,"套用投稿格式","fontFamily",()->draftTitle.setText(guidance.title(defaultTitle(result.optString("title")))));button(card,"检查官网规范","help",()->{try{SubmissionGuideUi.showReport(host,guidance.guide,draftTitle.getText().toString(),previewBody(),guidance.categories(),guidance.tree,guidance.kind(),guidance.aiImages.isChecked());}catch(Exception e){status.setText("无法检查草稿，请核对正文格式");}});}
        LinearLayout article=ui.column();ui.pad(article,13,14,13,14);article.setBackground(ui.round(ui.bg,14));card.addView(article);JSONArray translated=result.optJSONArray("blocks");if(translated!=null){for(int i=0;i<translated.length();i++){JSONObject b=translated.getJSONObject(i);if(b.optString("kind").equals("image")){ImageView photo=new ImageView(host);photo.setAdjustViewBounds(true);photo.setScaleType(ImageView.ScaleType.FIT_CENTER);photo.setContentDescription("原文介绍图片");article.addView(photo,new LinearLayout.LayoutParams(-1,ui.dp(210)));host.pictures().into(b.getString("url"),photo);ui.space(article,10);}else{TextView content=ui.text(b.optString("text"),14,ui.text,b.optString("kind").startsWith("h"));content.setLineSpacing(ui.dp(5),1.1f);content.setTextIsSelectable(true);article.addView(content);ui.space(article,12);}}}else{TextView content=ui.text(android.text.Html.fromHtml(AiClient.body(result),android.text.Html.FROM_HTML_MODE_COMPACT).toString(),14,ui.text,false);content.setTextIsSelectable(true);article.addView(content);}
        if(selfPurchased!=null&&selfPurchased.isChecked()&&!proofUrl.isEmpty()){article.addView(ui.text("自购证明",14,ui.text,true));ImageView photo=new ImageView(host);photo.setScaleType(ImageView.ScaleType.FIT_CENTER);photo.setContentDescription("自购证明");article.addView(photo,new LinearLayout.LayoutParams(-1,ui.dp(180)));host.pictures().into(proofUrl,photo);}
        ui.space(card,14);card.addView(ui.text("导入选项",13,ui.text,true));titleCheck=check(card,"替换标题",true);bodyCheck=check(card,"导入正文",true);coverCheck=check(card,"使用来源封面",false);appendCheck=check(card,"追加到正文（取消则替换）",true);
        if(guidance!=null){categoryCheck=check(card,"使用已确认分类（替换）",false);text(card,guidance.path().isEmpty()?"未确认分类，保留原选择。":guidance.path()+" · 同时包含上级分类");}
        importAction.setVisibility(View.VISIBLE);generate.setText("重新生成");
    }catch(Exception e){status.setText("草稿格式错误，原素材已保留，请重试");}}
    private String defaultTitle(String title){ArrayList<String> urls=new ArrayList<>();JSONArray list=result==null?null:result.optJSONArray("sources");if(list!=null)for(int i=0;i<list.length();i++)urls.add(list.optJSONObject(i).optString("url"));return SubmissionExtras.withDlsiteIds(title,urls);}
    private String previewBody()throws Exception{String body=AiClient.body(result);return selfPurchased!=null&&selfPurchased.isChecked()&&!proofUrl.isEmpty()?SubmissionExtras.placePurchaseProof(body,proofUrl):body;}
    private void purchaseForm(LinearLayout form){
        selfPurchased=check(form,"自购资源（仅本人购买时勾选）",false);proofBox=ui.column();form.addView(proofBox);selfPurchased.setOnCheckedChangeListener((v,on)->{refreshProof();if(result!=null)preview();});refreshProof();
    }
    private void refreshProof(){
        if(proofBox==null)return;proofBox.removeAllViews();proofBox.setVisibility(selfPurchased.isChecked()?View.VISIBLE:View.GONE);if(!selfPurchased.isChecked())return;
        panels.note(proofBox,"自购需一张证明，非自购无需上传。请先遮盖邮箱、订单号等私人信息。图片上传官网图床，导入后随正文公开，不交给AI。");
        if(!proofUrl.isEmpty()){ImageView photo=new ImageView(host);photo.setScaleType(ImageView.ScaleType.FIT_CENTER);photo.setContentDescription("自购证明预览");proofBox.addView(photo,new LinearLayout.LayoutParams(-1,ui.dp(160)));host.pictures().into(proofUrl,photo);}
        button(proofBox,proofUrl.isEmpty()?"上传自购证明":"更换证明图片","image",this::pickProof);if(!proofUrl.isEmpty())button(proofBox,"移除证明","close",()->{proofUrl="";refreshProof();if(result!=null)preview();});
    }
    private void proofBusy(boolean value){busy=value;for(View v:controls)v.setEnabled(!value);progress.setVisibility(value?View.VISIBLE:View.GONE);cancelAction.setVisibility(View.GONE);}
    private void pickProof(){
        if(busy||!live())return;proofBusy(true);proofPending=true;status.setText("选择一张自购证明；仅上传官网图床");android.content.Intent intent=new android.content.Intent(android.content.Intent.ACTION_OPEN_DOCUMENT);intent.setType("image/*");intent.addCategory(android.content.Intent.CATEGORY_OPENABLE);try{host.startActivityForResult(intent,6202);}catch(android.content.ActivityNotFoundException e){proofPending=false;proofBusy(false);status.setText("设备没有可用的图片选择器");}
    }
    void onProofResult(int code,android.content.Intent data){
        if(!proofPending)return;proofPending=false;if(!live())return;if(code!=Activity.RESULT_OK||data==null||data.getData()==null){proofBusy(false);status.setText("未选择证明图片");return;}
        final long job=++serial,session=host.client().sessionVersion();final android.net.Uri uri=data.getData();
        host.task(()->{try{return proofReader.read(uri);}catch(OutOfMemoryError e){throw new java.io.IOException("图片尺寸过大，请选择较小的图片");}},bytes->{if(!live()||job!=serial)return;
            ImageView photo=new ImageView(host);photo.setImageBitmap(android.graphics.BitmapFactory.decodeByteArray(bytes,0,bytes.length));photo.setScaleType(ImageView.ScaleType.FIT_CENTER);LinearLayout confirm=ui.column();ui.pad(confirm,16,14,16,14);confirm.addView(photo,new LinearLayout.LayoutParams(-1,ui.dp(220)));panels.note(confirm,"将上传官网图床，导入后随正文公开。请确认已遮盖私人信息。");
            AlertDialog ask=dialog().setTitle("上传这张自购证明？").setView(confirm).setNegativeButton("取消",(d,w)->{if(live()){proofBusy(false);status.setText("已取消证明上传");}}).setPositiveButton("上传",(d,w)->{
                if(!live()||job!=serial||host.client().sessionVersion()!=session){if(live())proofBusy(false);return;}status.setText("正在上传官网图床…");host.task(()->host.client().upload("upload/image","image",bytes,Collections.emptyMap(),"image/jpeg",session),response->{if(!live()||job!=serial)return;proofBusy(false);JSONObject detail=response.optJSONObject("data");String url=detail==null?response.optString("url",response.optString("link")):detail.optString("url",detail.optString("link"));if(url.startsWith("//"))url="https:"+url;else if(url.startsWith("/"))url=UrlPolicy.ORIGIN+url;if(!url.startsWith("https://")||!UrlPolicy.isImage(url)){status.setText("官网没有返回有效图片地址，请重新上传");return;}proofUrl=url;refreshProof();if(result!=null)preview();status.setText("证明已上传，导入时将放在下载模块之前");},message->{if(live()&&job==serial){proofBusy(false);status.setText(message);}});
            }).create();ask.setOnCancelListener(d->{if(live()){proofBusy(false);status.setText("已取消证明上传");}});ask.show();
        },message->{if(live()&&job==serial){proofBusy(false);status.setText(message);}});
    }
    private void importDraft(){
        if(busy||!live()||result==null)return;if(selfPurchased!=null&&selfPurchased.isChecked()&&(proofUrl.isEmpty()||!bodyCheck.isChecked())){status.setText(proofUrl.isEmpty()?"自购资源请先上传一张自购证明":"自购证明需随正文导入，请勾选导入正文");return;}draftTitle.setText(defaultTitle(draftTitle.getText().toString()));if(titleCheck.isChecked()&&draftTitle.getText().toString().trim().isEmpty()){draftTitle.setError("请补充投稿标题");return;}if(guidance!=null&&categoryCheck.isChecked()&&guidance.categories().isEmpty()){status.setText("请先确认当前目录中的分类");return;}
        dialog().setTitle("导入这份草稿？").setMessage("选中的标题、分类或封面将替换原字段。正文按你的选择追加或替换，尚未提交网站。").setNegativeButton("继续检查",null).setPositiveButton("导入",(d,w)->{if(!live())return;Import out=new Import();try{out.draft=new JSONObject(result.toString());out.draft.put("title",draftTitle.getText().toString().trim());if(guidance!=null){out.kind=guidance.kind();out.aiImages=guidance.aiImages.isChecked();if(categoryCheck.isChecked())out.categories=new LinkedHashSet<>(guidance.categories());}}catch(Exception e){status.setText("无法读取投稿标题");return;}out.purchaseProof=selfPurchased!=null&&selfPurchased.isChecked()?proofUrl:"";out.title=titleCheck.isChecked();out.body=bodyCheck.isChecked();out.tags=false;out.cover=coverCheck.isChecked();out.append=appendCheck.isChecked();imported.accept(out);window.dismiss();}).show();
    }
